import Foundation

// FM4: Furniture mode parts and forms (Docs/FurnitureMode.md §2): each part tool is named and behaves as its Revit-style
// Architecture counterpart (Panel ~ Wall, Shelf ~ Floor, Leg ~ Column, Rail ~ Beam, Slats ~ Beam System, Edge Profile
// and Groove ~ Wall Sweep and Reveal), and the forms are the Family Editor's. Aliases follow Revit's two-letter style;
// PN is Pin, so Panel is PA.

extension CommandCatalog {
    static let fm4Commands: [CommandInfo] = [
        CommandInfo(.furniturePanel, "Panel", .build, "rectangle.portrait", aliases: ["PA"],
                    help: "Draws sheet panels (sides, aprons, backs) like walls: by line, chain, rectangle or picked lines, in plan or in an elevation. Space flips the outside face.",
                    keywords: ["furniture", "side", "gable", "board", "wall", "carcass"]),
        CommandInfo(.furnitureShelf, "Shelf", .build, "rectangle.split.3x1", aliases: ["SH"],
                    help: "Sketches a shelf or bottom like a floor: draw its boundary or Pick Panels, then Finish.", keywords: ["furniture", "shelf", "bottom", "floor", "board"]),
        CommandInfo(.furnitureTop, "Top", .build, "rectangle.topthird.inset.filled", aliases: ["TP"],
                    help: "Sketches a top like a floor, its edges past the carcass by the type's overhang.", keywords: ["furniture", "top", "worktop", "counter", "tabletop"]),
        CommandInfo(.furnitureBack, "Back", .build, "rectangle.inset.filled", aliases: ["BK"],
                    help: "Places a back across a carcass: click inside it in an elevation; fits inside or over the back edges.", keywords: ["furniture", "back", "hardboard"]),
        CommandInfo(.furnitureDivider, "Divider", .build, "rectangle.split.2x1", aliases: ["DV"],
                    help: "Splits a bay into equal spaces with vertical or horizontal panels (EQ): click inside the bay in an elevation.", keywords: ["furniture", "divider", "partition", "fixed shelf"]),
        CommandInfo(.furnitureLeg, "Leg", .build, "rectangle.portrait.arrowtriangle.2.inward", aliases: ["LG"],
                    help: "Places legs like columns at points; Space rotates. At Corners places one in each corner of a top.", keywords: ["furniture", "leg", "foot", "column", "post"]),
        CommandInfo(.furnitureLegsAtCorners, "At Corners", .build, "square.grid.2x2",
                    help: "Places a leg in each corner of the picked top or shelf, inset from its edges, up to its underside.", keywords: ["furniture", "legs", "corners", "at grids"]),
        CommandInfo(.furnitureRail, "Rail", .build, "line.horizontal.3", aliases: ["RL"],
                    help: "Draws stretchers, aprons and cleats like beams between two points, with Z Justification.", keywords: ["furniture", "rail", "stretcher", "apron", "cleat", "beam"]),
        CommandInfo(.furnitureSlats, "Slats", .build, "square.split.bottomrightquarter", aliases: ["SLT"],
                    help: "Fills a region with slats at a spacing or number, as a beam system (bench seats, bed bases).", keywords: ["furniture", "slats", "beam system", "bed"]),
        CommandInfo(.furniturePlinth, "Plinth", .build, "rectangle.bottomthird.inset.filled", aliases: ["KK"],
                    help: "Runs a toe kick under the front of a bottom: pick the bottom, set the setback.", keywords: ["furniture", "plinth", "kick", "toe kick", "base"]),
        CommandInfo(.furnitureEdgeProfile, "Edge Profile", .build, "square.on.square.squareshape.controlhandles", aliases: ["EP"],
                    help: "Runs a profile along part edges (round-over, chamfer, bullnose, ogee, cove, finger pull), as a wall sweep.", keywords: ["furniture", "edge", "router", "sweep", "moulding"]),
        CommandInfo(.furnitureGroove, "Groove", .build, "square.split.diagonal", aliases: ["GV"],
                    help: "Cuts a groove along a part edge at an offset, as a wall reveal.", keywords: ["furniture", "groove", "dado", "reveal"]),
        CommandInfo(.furnitureEditProfile, "Edit Profile", .modify, "skew",
                    help: "Sketches a new outline for the selected panel in an elevation that looks at its face.", keywords: ["furniture", "panel", "profile", "shape"]),
        CommandInfo(.furnitureResetProfile, "Reset Profile", .modify, "arrow.counterclockwise",
                    help: "Restores the selected panels' rectangular outline.", keywords: ["furniture", "panel", "profile"]),
        CommandInfo(.furnitureAttach, "Attach Top/Base", .modify, "arrow.up.to.line",
                    help: "Runs the selected panels or legs to a shelf or top you pick: tops to its underside, bases to its top face.", keywords: ["furniture", "attach"]),
        CommandInfo(.furnitureDetach, "Detach Top/Base", .modify, "arrow.up.to.line.compact",
                    help: "Detaches the selected panels and legs from their shelf or top.", keywords: ["furniture", "detach"]),
        CommandInfo(.furniturePanelOpening, "Opening", .modify, "rectangle.dashed",
                    help: "Cuts a rectangular opening in a panel: pick two corners on its face in an elevation.", keywords: ["furniture", "opening", "cut-out", "hole"]),
        CommandInfo(.furnitureFlipPanel, "Flip Panel", .modify, "arrow.left.arrow.right.square",
                    help: "Swaps the outside and inside faces of the selected panels.", keywords: ["furniture", "flip"]),
        CommandInfo(.furnitureExtrusion, "Extrusion", .build, "cube",
                    help: "Sketches a closed profile on the work plane and extrudes it.", keywords: ["furniture", "form", "extrusion", "solid"]),
        CommandInfo(.furnitureBlend, "Blend", .build, "cone",
                    help: "Sketches a base loop and a top loop, and blends between them.", keywords: ["furniture", "form", "blend", "taper"]),
        CommandInfo(.furnitureRevolve, "Revolve", .build, "rotate.3d",
                    help: "Sketches a profile and an axis line in an elevation, and turns the profile about the axis.", keywords: ["furniture", "form", "revolve", "turned"]),
        CommandInfo(.furnitureSweep, "Sweep", .build, "point.topleft.down.curvedto.point.bottomright.up",
                    help: "Sketches a path and a profile, and sweeps the profile along the path.", keywords: ["furniture", "form", "sweep", "moulding"]),
        CommandInfo(.furnitureSweptBlend, "Swept Blend", .build, "point.bottomleft.forward.to.point.topright.scurvepath",
                    help: "Sweeps a profile along a path, changing to a second profile at its end.", keywords: ["furniture", "form", "swept blend"]),
        CommandInfo(.furnitureCushion, "Cushion", .build, "rectangle.roundedtop", aliases: ["CU"],
                    help: "Places a cushion: a box with a crowned top, rounded corners and piping.", keywords: ["furniture", "upholstery", "cushion", "seat", "foam"]),
        CommandInfo(.furnitureVoidExtrusion, "Void Extrusion", .build, "cube.transparent",
                    help: "An extrusion that cuts the parts it reaches.", keywords: ["furniture", "void", "cut"]),
        CommandInfo(.furnitureVoidBlend, "Void Blend", .build, "cone",
                    help: "A blend that cuts the parts it reaches.", keywords: ["furniture", "void", "cut"]),
        CommandInfo(.furnitureVoidRevolve, "Void Revolve", .build, "rotate.3d",
                    help: "A revolve that cuts the parts it reaches.", keywords: ["furniture", "void", "cut"]),
        CommandInfo(.furnitureVoidSweep, "Void Sweep", .build, "point.topleft.down.curvedto.point.bottomright.up",
                    help: "A sweep that cuts the parts it reaches.", keywords: ["furniture", "void", "cut"]),
        CommandInfo(.furnitureVoidSweptBlend, "Void Swept Blend", .build, "point.bottomleft.forward.to.point.topright.scurvepath",
                    help: "A swept blend that cuts the parts it reaches.", keywords: ["furniture", "void", "cut"]),
    ]
}
